}"}

{"plan_objective_id": 6, "updated_plan_objective_json": "{
  "id": 6,
  "objective": "Look for studies on standardless vs standards-based EDS quantification (NIST DTSA-II, pure-element standards) and the effect of accelerating voltage, count statistics, and surface preparation",
  "rationale": "The user needs to understand how these methodological parameters affect accuracy for their calibration protocol",
  "status": "completed",
